const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point(-49.053062, -1.593993);
  const aoi = point.buffer(100000); // 100 km radius
  const dateStart = '2009-08-19';
  const dateEnd = '2009-08-20';

  // 2. Data Acquisition & Pre-processing
  const landsatCollection = ee.ImageCollection('LANDSAT/LT05/C02/T1_TOA')
    .filterBounds(aoi)
    .filterDate(dateStart, dateEnd);

  const collectionSize = landsatCollection.size().getInfo();
  if (collectionSize === 0) {
    console.log("Image collection is empty for the specified date and location.");
    console.log("A: No");
    return;
  }

  const image = landsatCollection.mosaic().clip(aoi);

  // 3. Create Masks
  // Cloud mask from the QA_PIXEL band (Bit 3 is cloud)
  const qa = image.select('QA_PIXEL');
  const cloudMask = qa.bitwiseAnd(1 << 3).neq(0); // 1 for cloud, 0 for clear

  // Water mask using JRC Global Surface Water dataset
  const gsw = ee.Image('JRC/GSW1_4/GlobalSurfaceWater').select('occurrence');
  const waterMask = gsw.gte(50); // Areas with >50% water occurrence are considered water
  const landMask = waterMask.not();

  // 4. Calculate Cloud Cover over Land vs. Water
  const scale = 1000; // Use a larger scale to avoid timeout

  // Calculate total land and water pixels
  const landArea = landMask.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9
  }).get('occurrence');

  const waterArea = waterMask.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9
  }).get('occurrence');

  // Calculate cloudy pixels over land and water
  const cloudyLand = cloudMask.updateMask(landMask).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9
  }).get('QA_PIXEL');

  const cloudyWater = cloudMask.updateMask(waterMask).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9
  }).get('QA_PIXEL');

  // Use evaluate to fetch results concurrently
  const results = await new Promise((resolve, reject) => {
      ee.Dictionary({
          landArea: landArea,
          waterArea: waterArea,
          cloudyLand: cloudyLand,
          cloudyWater: cloudyWater
      }).evaluate((data, error) => {
          if (error) reject(error);
          else resolve(data);
      });
  });

  if (results.landArea === 0 || results.waterArea === 0) {
      console.log("No valid land or water pixels found in the AOI.");
      console.log("C2");
      return;
  }

  if (results.cloudyLand === null || results.cloudyWater === null || results.landArea === null || results.waterArea === null) {
      console.log("Calculation failed, a result was null.");
      console.log("C3");
      return;
  }

  // 5. Final Comparison and Answer
  const cloudCoverLand = (results.cloudyLand / results.landArea) * 100;
  const cloudCoverWater = (results.cloudyWater / results.waterArea) * 100;

  console.log(`Images found: ${collectionSize}`);
  console.log(`Cloud cover over Land: ${cloudCoverLand.toFixed(2)}%`);
  console.log(`Cloud cover over Water: ${cloudCoverWater.toFixed(2)}%`);

  if (cloudCoverLand > cloudCoverWater) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error("An error occurred: ", err);
    console.log("D");
});
